    </div>
  </div>
</div>',
      title = 'Why the Inbox Matters',
      lesson_number = 2,
      sort_order = 2,
      updated_at = NOW()
    WHERE id = v_lesson_id;
    
    RAISE NOTICE 'Updated lesson: Why the Inbox Matters';
  END IF;

END $$;


-- Insert Quiz Questions for Lesson: Why the Inbox Matters

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 4 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 4 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'why-inbox-matters' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson why-inbox-matters not found in module 4';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Why is the Conversations Inbox important for business growth?', 
    '["It automatically generates new leads","It helps you convert existing leads by responding quickly and effectively","It reduces your marketing costs","It replaces your website"]'::jsonb,
    'It helps you convert existing leads by responding quickly and effectively',
    'The inbox helps you make the most of leads you already have. Fast, helpful responses convert interested prospects into booked calls and sales.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What happens when a message goes unanswered?', 
    '["The lead waits indefinitely","You may lose the opportunity - the lead goes cold or chooses a competitor","The system automatically replies","Nothing - leads don''t expect responses"]'::jsonb,
    'You may lose the opportunity - the lead goes cold or chooses a competitor',
    'Unanswered messages often result in lost opportunities. Leads expect timely responses and will move on if they don''t hear back.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What is the main goal of inbox management?', 
    '["To answer as many messages as possible","To move conversations forward and convert leads","To keep the inbox empty","To automate all responses"]'::jsonb,
    'To move conversations forward and convert leads',
    'The goal isn''t just to clear messages - it''s to respond effectively and move each conversation toward a booking, sale, or next step.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;
